// Scroll progress
  const bar = document.getElementById('scroll-progress');
  window.addEventListener('scroll', () => {
    const h = document.body.scrollHeight - window.innerHeight;
    bar.style.width = h ? (window.scrollY / h * 100) + '%' : '0%';
  });

  // Header
  const hdr = document.getElementById('site-header');
  window.addEventListener('scroll', () => hdr.classList.toggle('scrolled', window.scrollY > 50));

  // Hamburger
  document.getElementById('hamburger').addEventListener('click', () => {
    document.getElementById('mobile-nav').classList.toggle('open');
  });

  // FAB + Chat
  const fab = document.getElementById('fab');
  const chat = document.getElementById('chat-widget');
  window.addEventListener('scroll', () => fab.classList.toggle('visible', window.scrollY > 300));
  fab.addEventListener('click', () => chat.classList.toggle('open'));
  document.getElementById('chat-close').addEventListener('click', () => chat.classList.remove('open'));

  // Footer year
  document.getElementById('footer-year').textContent = new Date().getFullYear();

  // Scroll to top
  window.scrollTo({ top: 0, behavior: 'instant' });

  // Auto-build Table of Contents
  (function buildTOC() {
    const prose = document.getElementById('article-prose');
    const list  = document.getElementById('toc-list');
    if (!prose || !list) return;

    const headings = prose.querySelectorAll('h2, h3');
    if (headings.length < 2) {
      document.getElementById('toc-container').style.display = 'none';
      return;
    }

    headings.forEach(h => {
      if (!h.id) {
        h.id = h.textContent.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
      }
      const li = document.createElement('li');
      if (h.tagName === 'H3') li.classList.add('toc-h3');
      const a = document.createElement('a');
      a.href = '#' + h.id;
      a.textContent = h.textContent;
      a.addEventListener('click', e => {
        e.preventDefault();
        document.getElementById(h.id)?.scrollIntoView({ behavior: 'smooth' });
      });
      li.appendChild(a);
      list.appendChild(li);
    });

    const observer = new IntersectionObserver(entries => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          list.querySelectorAll('a').forEach(a => a.classList.remove('active'));
          const active = list.querySelector(`a[href="#${entry.target.id}"]`);
          if (active) active.classList.add('active');
        }
      });
    }, { rootMargin: '-80px 0px -75% 0px' });

    headings.forEach(h => observer.observe(h));
  })();
